/*
 * A141882  Primes congruent to 7 mod 20.
 * https://oeis.org/A141882
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 7, u16 n <= 822, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: primes ≡ 7 (mod 20) – generated by trial division of candidates */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_prime.h"

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset is 1; index 0 is unused */

    static seq_t *cache = NULL;    /* array of found primes */
    static size_t cache_len = 0;   /* number of primes stored */
    static size_t cache_cap = 0;   /* allocated capacity */
    static idx_t  next_candidate = 7;   /* next number ≡ 7 (mod 20) to test */

    /* allocate initial cache if needed */
    if (cache == NULL) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (!cache) return 0;      /* allocation failure */
    }

    /* produce primes until we have at least n of them */
    while (cache_len < (size_t)n) {
        /* grow the cache when necessary */
        if (cache_len == cache_cap) {
            cache_cap <<= 1;               /* double capacity */
            seq_t *tmp = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            if (!tmp) return 0;            /* allocation failure */
            cache = tmp;
        }

        /* test the current candidate */
        if (is_prime(next_candidate))
            cache[cache_len++] = (seq_t)next_candidate;

        next_candidate += 20;              /* advance to the next ≡ 7 mod 20 */
    }

    return cache[n - 1];     /* a(1) is cache[0] */
}
